#include<bits/stdc++.h>
#include<tr1/unordered_map>
using namespace std;

inline void readInt(int &v) {
    static char ch;
    v = 0;
    bool neg = 0;
    do {
        ch = getchar();
        if(ch == '-') neg = 1;
    } while(!isdigit(ch));
    while(isdigit(ch)) {
        v = (v + (v << 2) << 1) + (ch ^ '0');
        ch = getchar();
    }
    if(neg) v = -v;
}

inline void readLL(long long &v) {
    static char ch;
    v = 0;
    bool neg = 0;
    do {
        ch = getchar();
        if(ch == '-') neg = 1;
    } while(!isdigit(ch));
    while(isdigit(ch)) {
        v = (v + (v << 2) << 1) + (ch ^ '0');
        ch = getchar();
    }
    if(neg) v = -v;
}

long long N, K, MOD;
int fact[262155];
int invFact[262155];

inline int modPow(int x, long long y) {
    int res = 1;
    while(y) {
        if(y & 1) res = (long long)res * x % MOD;
        x = (long long)x * x % MOD;
        y >>= 1;
    }
    return res;
}

int dp[262155][31];
bool visited[262155][31];
int log2Val[262155];

inline int trailingZeros(int x) {
    int cnt = 0;
    while(x && x % 2 == 0) {
        ++cnt;
        x /= 2;
    }
    return cnt;
}

int cumTrail[262155];

inline int binom(int n, int m) {
    return (long long)fact[n] * invFact[m] % MOD * invFact[n - m] % MOD;
}

inline int dfsDP(int n, int k) {
    if(n == 0) return 1;
    if(k == 0) return 0;
    if(dp[n][k] != -1) return dp[n][k];
    int low = (1 << log2Val[n]), ret = 0;
    for(int i = n; i >= low; i -= 2) {
        ret = (ret + (long long)binom(n, i) * dfsDP(n - i, k - 1) % MOD * k) % MOD;
    }
    return dp[n][k] = ret;
}

vector<pair<int,int>> order;
inline int bfsDP(int n, int k) {
    static queue<pair<int,int>> q;
    q.push({n, k});
    while(!q.empty()) {
        n = q.front().first, k = q.front().second;
        q.pop();
        order.push_back({n, k});
        if(n == 0 || k == 0) continue;
        int low = (1 << log2Val[n]);
        for(int i = n; i >= low; i -= 2) {
            if(cumTrail[i] + cumTrail[n - i] == cumTrail[n] && !visited[n - i][k - 1]) {
                visited[n - i][k - 1] = 1;
                q.push({n - i, k - 1});
            }
        }
    }
    for(int idx = order.size() - 1; idx >= 0; --idx) {
        n = order[idx].first, k = order[idx].second;
        if(n == 0) { dp[n][k] = 1; continue; }
        if(k == 0) { dp[n][k] = 0; continue; }
        int low = (1 << log2Val[n]);
        for(int i = n; i >= low; i -= 2) {
            if(cumTrail[i] + cumTrail[n - i] == cumTrail[n])
                dp[n][k] = (dp[n][k] + (long long)binom(n, i) * dp[n - i][k - 1] % MOD * k) % MOD;
        }
    }
    return dp[n][k];
}

int main() {
    readLL(N), readLL(K), readLL(MOD);
    fact[0] = 1;
    memset(visited, 0, sizeof(visited));
    log2Val[0] = -1;
    for(int i = 1; i <= 262150; ++i) {
        fact[i] = (long long)fact[i - 1] * i % MOD;
        log2Val[i] = log2Val[i >> 1] + 1;
        cumTrail[i] = cumTrail[i - 1] + trailingZeros(i);
    }
    invFact[262150] = modPow(fact[262150], MOD - 2);
    for(int i = 262149; i; --i) invFact[i] = (long long)invFact[i + 1] * (i + 1) % MOD;
    invFact[0] = invFact[1];
    if(N & 1) {
        printf("%lld\n", modPow(K, N));
    } else {
        int ans = modPow(K, N);
        ans = (ans - bfsDP(N, K) + MOD) % MOD;
        printf("%d\n", ans);
    }
    return 0;
}
